-- HUDDLE API-private schema. Do not add huddle to Supabase exposed schemas.
CREATE SCHEMA IF NOT EXISTS huddle;
SET LOCAL search_path TO huddle, pg_catalog;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created INTEGER NOT NULL,disabled INTEGER);
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active',data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS divisions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,data TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS templates(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,data TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),account_id TEXT NOT NULL REFERENCES accounts(id),role TEXT NOT NULL CHECK(role IN ('owner','admin','member')),division_id TEXT,data TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL,disabled INTEGER,UNIQUE(tenant_id,id),UNIQUE(tenant_id,account_id),FOREIGN KEY(tenant_id,division_id) REFERENCES divisions(tenant_id,id));
CREATE TABLE IF NOT EXISTS cards(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,template_id TEXT NOT NULL,persona TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,data TEXT NOT NULL,blocks TEXT NOT NULL DEFAULT '{}',is_default INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL,updated INTEGER NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,user_id,id),FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,template_id) REFERENCES templates(tenant_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS one_default_card ON cards(tenant_id,user_id) WHERE is_default=1;
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),active_tenant_id TEXT NOT NULL,expires INTEGER NOT NULL,FOREIGN KEY(active_tenant_id,account_id) REFERENCES users(tenant_id,account_id));
CREATE TABLE IF NOT EXISTS invitations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),email TEXT NOT NULL,data TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,token TEXT NOT NULL,status TEXT NOT NULL,delivery TEXT NOT NULL,created INTEGER NOT NULL,expires INTEGER NOT NULL,provider_id TEXT);
CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),email TEXT NOT NULL,data TEXT NOT NULL,password TEXT NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),actor TEXT NOT NULL,action TEXT NOT NULL,subject TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS nfc_cards(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,card_id TEXT NOT NULL,token TEXT NOT NULL UNIQUE,label TEXT NOT NULL,tag_hash TEXT,active INTEGER NOT NULL,created INTEGER NOT NULL,written INTEGER,FOREIGN KEY(tenant_id,card_id) REFERENCES cards(tenant_id,id));
CREATE TABLE IF NOT EXISTS activity(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,card_id TEXT NOT NULL,kind TEXT NOT NULL,source TEXT NOT NULL,visitor TEXT NOT NULL,label TEXT NOT NULL,created INTEGER NOT NULL,FOREIGN KEY(tenant_id,user_id,card_id) REFERENCES cards(tenant_id,user_id,id));
CREATE TABLE IF NOT EXISTS contact_exchanges(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,card_id TEXT NOT NULL,data TEXT NOT NULL,consent_version TEXT NOT NULL,consented_at INTEGER NOT NULL,source TEXT NOT NULL,created INTEGER NOT NULL,FOREIGN KEY(tenant_id,user_id,card_id) REFERENCES cards(tenant_id,user_id,id));
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES organizations(id),uploaded_by TEXT NOT NULL,storage_key TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('private','public')),created INTEGER NOT NULL,UNIQUE(tenant_id,storage_key));
CREATE TABLE IF NOT EXISTS wallet_passes(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,card_id TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN ('apple','google')),provider_reference TEXT,status TEXT NOT NULL,created INTEGER NOT NULL,FOREIGN KEY(tenant_id,card_id) REFERENCES cards(tenant_id,id));
CREATE INDEX IF NOT EXISTS activity_tenant_date ON activity(tenant_id,created,user_id,card_id);
CREATE INDEX IF NOT EXISTS leads_tenant_member ON contact_exchanges(tenant_id,user_id,created);
CREATE INDEX IF NOT EXISTS cards_tenant_member ON cards(tenant_id,user_id);
CREATE INDEX IF NOT EXISTS invite_tenant_email ON invitations(tenant_id,email,status);

CREATE TABLE IF NOT EXISTS user_security(tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,secret TEXT,pending_secret TEXT,enabled INTEGER NOT NULL DEFAULT 0,recovery_hashes TEXT NOT NULL DEFAULT '[]',last_counter INTEGER NOT NULL DEFAULT -1,PRIMARY KEY(tenant_id,user_id),FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id));
CREATE TABLE IF NOT EXISTS auth_challenges(token_hash TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,account_id TEXT NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,used INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id));
CREATE TABLE IF NOT EXISTS oauth_states(state_hash TEXT PRIMARY KEY,verifier TEXT NOT NULL,nonce TEXT NOT NULL,browser_hash TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0,context TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS oauth_identities(provider TEXT NOT NULL,subject TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES accounts(id),PRIMARY KEY(provider,subject));

ALTER TABLE sessions ADD COLUMN IF NOT EXISTS mfa_tenant TEXT;
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS mfa_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS authenticated_at INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT NOT NULL,window_start BIGINT NOT NULL,hits INTEGER NOT NULL,expires BIGINT NOT NULL,PRIMARY KEY(key,window_start));
CREATE INDEX IF NOT EXISTS rate_limit_expiry ON rate_limits(expires);
INSERT INTO schema_migrations VALUES(1,EXTRACT(EPOCH FROM NOW())::INTEGER),(2,EXTRACT(EPOCH FROM NOW())::INTEGER) ON CONFLICT DO NOTHING;
